    ('ece7f01a-17bf-4b09-afc9-8368b323a88b'::uuid, 'period_name', 'Undated', NULL, 'period-label-undated-2026-10-04e-rollback:ece7f01a-17bf-4b09-afc9-8368b323a88b:period_name', 'rollback of period-label-undated-2026-10-04e: period_name None restored on Rodadero Slides', 'no period_start', '[{"source": "output/remediation/period_wave/residue_rule.json", "url": "output/remediation/period_wave/residue_rule.json", "quote": "\"period_name\": \"Undated\", \"period_start\": null, \"marked_unproven\": true"}, {"source": "pipeline/utils/text.py", "url": "pipeline/utils/text.py", "quote": "UNDATED = \"Undated\""}]'::jsonb),
    ('ee94fe5e-d975-4ed9-940d-16056532293e'::uuid, 'period_name', 'Undated', NULL, 'period-label-undated-2026-10-04e-rollback:ee94fe5e-d975-4ed9-940d-16056532293e:period_name', 'rollback of period-label-undated-2026-10-04e: period_name None restored on Beşkardeşler Kaya Mezarları', 'no period_start', '[{"source": "output/remediation/period_wave/residue_rule.json", "url": "output/remediation/period_wave/residue_rule.json", "quote": "\"period_name\": \"Undated\", \"period_start\": null, \"marked_unproven\": true"}, {"source": "pipeline/utils/text.py", "url": "pipeline/utils/text.py", "quote": "UNDATED = \"Undated\""}]'::jsonb),
