    ('f6daed37-710f-4512-a494-bb4ecddd4d2c'::uuid, 'period_name', 'Undated', NULL, 'period-label-undated-2026-10-04e-rollback:f6daed37-710f-4512-a494-bb4ecddd4d2c:period_name', 'rollback of period-label-undated-2026-10-04e: period_name None restored on Cave of El Soplao', 'no period_start', '[{"source": "output/remediation/period_wave/residue_rule.json", "url": "output/remediation/period_wave/residue_rule.json", "quote": "\"period_name\": \"Undated\", \"period_start\": null, \"marked_unproven\": true"}, {"source": "pipeline/utils/text.py", "url": "pipeline/utils/text.py", "quote": "UNDATED = \"Undated\""}]'::jsonb),
    ('facb2c7f-777a-4eb0-8036-731853847f07'::uuid, 'period_name', 'Undated', NULL, 'period-label-undated-2026-10-04e-rollback:facb2c7f-777a-4eb0-8036-731853847f07:period_name', 'rollback of period-label-undated-2026-10-04e: period_name None restored on Kunturmarka, Ayacucho', 'no period_start', '[{"source": "output/remediation/period_wave/residue_rule.json", "url": "output/remediation/period_wave/residue_rule.json", "quote": "\"period_name\": \"Undated\", \"period_start\": null, \"marked_unproven\": true"}, {"source": "pipeline/utils/text.py", "url": "pipeline/utils/text.py", "quote": "UNDATED = \"Undated\""}]'::jsonb),
    ('faf8f8ee-c092-48a8-a712-1133df65badd'::uuid, 'period_name', 'Undated', NULL, 'period-label-undated-2026-10-04e-rollback:faf8f8ee-c092-48a8-a712-1133df65badd:period_name', 'rollback of period-label-undated-2026-10-04e: period_name None restored on Pukara, Víctor Fajardo', 'no period_start', '[{"source": "output/remediation/period_wave/residue_rule.json", "url": "output/remediation/period_wave/residue_rule.json", "quote": "\"period_name\": \"Undated\", \"period_start\": null, \"marked_unproven\": true"}, {"source": "pipeline/utils/text.py", "url": "pipeline/utils/text.py", "quote": "UNDATED = \"Undated\""}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 103;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _period_label_undated_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'period_name undated: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _period_label_undated_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'period_name' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.old_value IS NULL OR length(p.new_value) > 100
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name undated: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _period_label_undated_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name undated: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _period_label_undated_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.old_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD', 'Undated')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name undated: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _period_label_undated_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (CASE WHEN u.period_start IS NULL THEN 'no period_start' ELSE u.period_start::text END) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name undated: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _period_label_undated_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'period-label/residue', '2026-10-04e_period-label-undated-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'period_name undated: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _period_label_undated_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name undated: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _period_label_undated_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-04e_period-label-undated-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name undated: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-04e_period-label-undated-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('period_name'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'period_name undated: this run stamp journalled % row(s) outside unified_sites.(period_name)', bad;
    END IF;

    RAISE NOTICE 'period_name undated: % of % planned cell(s) changed and journalled over 103 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-04e_period-label-undated-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'period-label/residue'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-10-04e_period-label-undated-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('period_name')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM l.new_value::text
                ELSE false END)
UNION ALL
SELECT 'curated rows whose period_name is not the bucket of period_start, or not Undated where there is none', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND period_name IS DISTINCT FROM (CASE WHEN period_start IS NULL THEN 'Undated' WHEN period_start < -4500 THEN '< 4500 BC' WHEN period_start < -3000 THEN '4500 - 3000 BC' WHEN period_start < -1500 THEN '3000 - 1500 BC' WHEN period_start < -500 THEN '1500 - 500 BC' WHEN period_start < 1 THEN '500 BC - 1 AD' WHEN period_start < 500 THEN '1 - 500 AD' WHEN period_start < 1000 THEN '500 - 1000 AD' WHEN period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END)
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
